def rule_checks(a):
    """-> per-rollout dict (key S_arm_s<m>) of control r7 for the rollouts of GEc and A90 at the new model seeds: the model reader's w2_one against the run's own gap file (the base file for GEc, the scaled file
    for A90), the meta of the rule log naming that file's hash and the closing switch; the reference rows for the lead steps where the file has no output come from the rule log of the reference run RR of the
    setting at the SAME model seed."""
    per = {}
    for S in SETTINGS:
        for arm in RULE_ARMS:
            gf = gap_file_of(a, arm)
            for m in SEEDS:
                key = "%s_%s_s%d" % (S, arm, m)
                try:
                    if not gf or not os.path.isfile(gf):
                        per[key] = {"PASS": False, "failures": ["no gap file %s" % gf]}
                        continue
                    gref = MD.gapfile_ref(gf)
                    fsha = sha_file(gf)
                    logs = load_logs_setting(a.pull, run_name(S, arm), m, S)
                    ref_logs = load_logs_setting(a.pull, run_name(S, "RR"), m, S)
                    v0 = MD.lead_multi(MD.rows_of(ref_logs))
                    meta = MD.meta_of(logs[0])
                    r = MD.w2_one(MD.rows_of(logs), gref, v0, meta_expect={"vis_closing": 1}, meta=meta)
                    ms = str(meta.get("vis_gap_file_sha256") or "").lower()
                    if not (len(ms) >= 16 and (fsha.startswith(ms) or ms.startswith(fsha))):
                        r["failures"] = list(r.get("failures", [])) + ["rule log meta names the gap file hash %s, the gap file on disk has %s" % (ms[:16] or None, fsha[:16])]
                        r["PASS"] = False
                    per[key] = r
                except (SystemExit, OSError, ValueError, KeyError) as ex:
                    per[key] = {"PASS": False, "failures": ["cannot read the rollout, its reference or its gap file: %s: %s" % (type(ex).__name__, ex)]}
    return per


def _hash_match(x, y):
    x, y = str(x or "").lower(), str(y or "").lower()
    return len(x) >= 16 and len(y) >= 16 and (x.startswith(y) or y.startswith(x))


def ctl_gap(rec, sha_base, shas):
    """gap-file record (control k0 of card ADD117, part of e1 here), scaled gap files: the record GAPMARGIN_GAPFILES_RECORD.json has pass_k0 true, the scale of one gave the base arrays, every clause of both files is true, and the base
    file and both scaled files on disk have the hashes the record holds; the base file is the one of card ADD106 (sha256 begins 55de2f7c). shas {arm: sha256 of its scaled file on disk}."""
    bad = []
    rec = rec if isinstance(rec, dict) else {}
    if rec.get("pass_k0") is not True:
        bad.append("the record of the scaled gap files has pass_k0 %s" % rec.get("pass_k0"))
    if rec.get("scale_one_gives_the_base_arrays") is not True:
        bad.append("the record does not say that the scale of one gives the base arrays")
    want_b = (rec.get("base") or {}).get("sha256")
    if not sha_base or not want_b or str(sha_base).lower() != str(want_b).lower():
        bad.append("the base gap file on disk has sha256 %s, the record holds %s" % ((sha_base or "none")[:16], str(want_b or "none")[:16]))
    if not str(sha_base or "").startswith("55de2f7c"):
        bad.append("the base gap file is not the one of card ADD106 (sha256 %s)" % (sha_base or "none")[:16])
    newly = {}
    for arm in MARGIN_ARMS:
        nm = MARGIN_FILES[arm]
        cl = (rec.get("clauses") or {}).get(nm)
        if not isinstance(cl, dict) or not cl or not all(v is True for v in cl.values()):
            bad.append("%s: the clauses of the record are not all true" % nm)
        f = (rec.get("files") or {}).get(nm) or {}
        got = (shas or {}).get(arm)
        if not got or not f.get("sha256") or str(got).lower() != str(f.get("sha256")).lower():
            bad.append("%s on disk has sha256 %s, the record holds %s" % (nm, (got or "none")[:16], str(f.get("sha256") or "none")[:16]))
        want_a = {"A90": 0.90, "A80": 0.80}[arm]
        if f.get("a") is None or abs(float(f.get("a")) - want_a) > 1e-12:
            bad.append("%s: the record holds the scale %s, the card has %.2f" % (nm, f.get("a"), want_a))
        newly[arm] = f.get("n_rows_base_gap_above_60_and_scaled_at_most_60")
    return {"pass": not bad, "failures": bad, "values": {"n_rows_newly_in_range": newly, "counts": rec.get("counts")}}


def ctl_wrap(wrapper_sha16, check_text, hashes_text, check_files_present, run_shas):
    """wrapper control (control k1 of the source, part of e1 here): the wrapper file has the hash 28bc31f21ecb4ccb; the banked check files are in place, the pod check record ends with `ZZ CHECK-WRAPPER-V PASS` and the hashes name the wrapper; the run text of each of
    the six new runs names a wrapper hash that begins with it"""
    bad = []
    if wrapper_sha16 != WRAPPER_SHA:
        bad.append("the wrapper file is %s, not %s" % (wrapper_sha16, WRAPPER_SHA))
    if not check_files_present:
        bad.append("a banked check file of the wrapper is missing")
    if last_line(check_text).strip() != CHECK_LAST:
        bad.append("the last line of the pod check is %r" % last_line(check_text).strip())
    if WRAPPER_SHA not in (hashes_text or ""):
        bad.append("the pod check hashes do not name %s" % WRAPPER_SHA)
    for k in new_keys():
        v = run_shas.get(k)
        if v is None:
            bad.append("%s: the run text names no wrapper hash" % k)
        elif not v.startswith(WRAPPER_SHA):
            bad.append("%s: the run text names the wrapper hash %s" % (k, v[:16]))
    return {"pass": not bad, "failures": bad, "wrapper_sha16": wrapper_sha16}


def ref_arm(S, arm):
    """the reference run of a new run: the banked run of the same name at model seed m - 2 (the same arm)"""
    return arm


def spread_keys():
    return ["CONV_R0_s%d" % m for m in SEEDS]


def all_run_keys():
    """the 26 rollouts of this card: 24 arm runs and the two spread runs"""
    return new_keys() + spread_keys()


def rule_keys():
    return ["%s_%s_s%d" % (S, arm, m) for S in SETTINGS for arm in RULE_ARMS for m in SEEDS]


def run_list():
    """[(key, run name, setting, model seed)] of the 26 rollouts; the spread run is a CONV run"""
    out = [("%s_%s_s%d" % (S, arm, m), run_name(S, arm), S, m) for S, arm in new_pairs() for m in SEEDS]
    out += [("CONV_R0_s%d" % m, SPREAD, "CONV", m) for m in SEEDS]
    return out


def _is_hex(x, n):
    return isinstance(x, str) and len(x) == n and re.fullmatch(r"[0-9a-fA-F]+", x) is not None


def ctl_e0(rec, ckpt_shas, run_texts):
    """e0 models (r0): rec is the JSON that the lead writes, {"models": {"UE_s2": {...}, "UE_s3": {...}}, "note_sha256": <64 hex>}, each model with ckpt_sha256 (64 hex), gate_pass (true), recipe_same_but_seed
    (true) and record (text). For m in 2, 3: ckpt_shas[m] (the sha256 of <w>/ckpt/UE_s<m>/A/ckpt_last.pt on disk) equals the record's hash, and the first line of every new run of model seed m (run_texts
    {key: text}) names `ckpt sha256 <hex>` that agrees with the record's hash by prefix (at least 16 characters)."""
    bad = []
    rec = rec if isinstance(rec, dict) else {}
    models = rec.get("models") if isinstance(rec.get("models"), dict) else {}
    if not _is_hex(rec.get("note_sha256"), 64):
        bad.append("the record's note_sha256 is not 64 hex characters")
    for m in SEEDS:
        e = models.get("UE_s%d" % m)
        if not isinstance(e, dict):
            bad.append("UE_s%d: no entry in the record" % m)
            continue
        h = e.get("ckpt_sha256")
        if not _is_hex(h, 64):
            bad.append("UE_s%d: ckpt_sha256 is not 64 hex characters" % m)
        disk = (ckpt_shas or {}).get(m)
        if not disk:
            bad.append("UE_s%d: no checkpoint file on disk" % m)
        elif _is_hex(h, 64) and str(disk).lower() != h.lower():
            bad.append("UE_s%d: the checkpoint on disk has sha256 %s, the record holds %s" % (m, str(disk)[:16], h[:16]))
        if e.get("gate_pass") is not True:
            bad.append("UE_s%d: gate_pass is %s" % (m, e.get("gate_pass")))
        if e.get("recipe_same_but_seed") is not True:
            bad.append("UE_s%d: recipe_same_but_seed is %s" % (m, e.get("recipe_same_but_seed")))
        if not (isinstance(e.get("record"), str) and e.get("record").strip()):
            bad.append("UE_s%d: the record carries no text" % m)
    want_keys = sorted(all_run_keys())
    if sorted(run_texts or {}) != want_keys:
        bad.append("run texts read: %d keys, expected %d" % (len(run_texts or {}), len(want_keys)))
    for k, t in sorted((run_texts or {}).items()):
        m = int(k.rsplit("_s", 1)[1])
        h = ((models.get("UE_s%d" % m) or {}).get("ckpt_sha256")) if isinstance(models.get("UE_s%d" % m), dict) else None
        got = parse_run_line(t).get("ckpt")
        if not got:
            bad.append("%s: the first line names no ckpt sha256" % k)
        elif not _hash_match(got, h):
            bad.append("%s: the first line names the checkpoint %s, the record of model seed %d holds %s" % (k, str(got)[:16], m, str(h or "none")[:16]))
    return {"pass": not bad, "failures": bad, "values": {"ckpt_sha16": {str(m): str((ckpt_shas or {}).get(m) or "")[:16] for m in SEEDS}}}


def ctl_e1(gap, wrap):
    """e1 wrapper and gap files (r1): the source's gap-file record control for the scaled file A90 (ctl_gap) and the source's wrapper control (ctl_wrap) both pass"""
    bad = ["gap files: " + x for x in gap.get("failures", [])] + ["wrapper: " + x for x in wrap.get("failures", [])]
    if gap.get("pass") is not True or wrap.get("pass") is not True:
        bad = bad or ["a part of the control did not pass"]
    return {"pass": not bad, "failures": bad, "values": {"gap_files": gap.get("values"), "wrapper_sha16": wrap.get("wrapper_sha16")}}


def ctl_e2(lines):
    """e2 arguments (r2): lines {key: (text of the new run, text of the banked run of the same name at model seed m - 2)} for the 26 rollouts (d2_repl_failures)"""
    bad = []
    if sorted(lines) != sorted(all_run_keys()):
        bad.append("run lines read: %d keys, expected %d" % (len(lines), len(all_run_keys())))
    spec_of = {k: (S, m) for k, nm, S, m in run_list()}
    for k, (tn, tr) in sorted(lines.items()):
        if k not in spec_of:
            continue
        S, m = spec_of[k]
        if not first_line(tn):
            bad.append("%s: no run log of the new run" % k)
            continue
        if not first_line(tr):
            bad.append("%s: no run log of the banked run" % k)
            continue
        bad += ["%s: %s" % (k, x) for x in d2_repl_failures(parse_run_line(tn), parse_run_line(tr), S, m)]
    return {"pass": not bad, "failures": bad}


def d2_repl_failures(new, ref, S, m):
    """card r2 on two parsed first lines (the new run of model seed m, the banked run of the same name at model seed m - 2): every field both carry is equal but the model seed and the checkpoint hash;
    a compared field that the banked line carries and the new line lacks is a failure; the new line carries its model seed and its reader seed, the model seed is m and the reader seed is m - 2; a banked line
    that carries a model seed or a reader seed names m - 2; where the banked line carries no pre-roll, grid or nav the new line reads the default of the setting (pre-roll of the setting, its grid file,
    nav deadreckon)."""
    bad = []
    for k in ("model_seed", "reader_seed"):
        if k not in new:
            bad.append("the new line carries no %s" % k)
    if "model_seed" in new and not _same(new["model_seed"], m):
        bad.append("model seed: the new line reads %s, expected %d" % (new["model_seed"], m))
    if "reader_seed" in new and not _same(new["reader_seed"], m - 2):
        bad.append("reader seed: the new line reads %s, expected %d" % (new["reader_seed"], m - 2))
    for k in ("model_seed", "reader_seed"):
        if k in ref and not _same(ref[k], m - 2):
            bad.append("%s: the banked line reads %s, expected %d" % (k, ref[k], m - 2))
    if "ckpt" in new and "ckpt" in ref and new["ckpt"][:16].lower() == ref["ckpt"][:16].lower():
        bad.append("ckpt: the new line names the checkpoint hash of the banked run (%s)" % new["ckpt"][:16])
    for k in D2_COMPARED:
        if k in ("model_seed", "ckpt"):
            continue
        if k in new and k in ref and not _same(new[k], ref[k]):
            bad.append("%s: new %s, reference %s" % (k, new[k], ref[k]))
        if k in ref and k not in new:
            bad.append("%s: the banked line carries it (%s), the new line does not" % (k, ref[k]))
    gridname = PINNED_GRID_NAME if SPEC[S]["grid_file"] == "pinned" else SPEC[S]["grid_file"]
    for k, dflt in (("preroll", str(SPEC[S]["P"])), ("grid", gridname), ("nav", "deadreckon")):
        if k not in ref and not (k in new and _same(new[k], dflt)):
            bad.append("the banked line carries no %s, the new line has to read %s %s (it reads %s)" % (k, k, dflt, new.get(k)))
    return bad


def ctl_e3(levels):
    """e3 identity (r3): the reader reproduces within 1e-4 the banked levels (C, U, F) for GEc, A90, RLc, RR at CONV, K0 and K30 over the first pair of model seeds; read by the same code path as the new cells. levels {S: {arm: {C,U,F}}}"""
    bad = []
    for S, arms in EXPECTED.items():
        for arm, want in arms.items():
            for c, v in zip("CUF", want):
                got = (((levels or {}).get(S) or {}).get(arm) or {}).get(c)
                if got is None or not np.isfinite(got) or abs(float(got) - v) > LEVEL_TOL + 1e-12:
                    bad.append("%s %s %s: %s, expected %.4f within %g" % (S, arm, c, got, v, LEVEL_TOL))
    return {"pass": not bad, "failures": bad}


def _pytest_ok(text, nm):
    bad = []
    hits = re.findall(r"(\d+) passed", text or "")
    if not (hits and int(hits[-1]) > 0):
        bad.append("%s: no line with a count of passed tests above 0" % nm)
    if re.search(r"\b\d+ (failed|errors?)\b", text or ""):
        bad.append("%s: the test output has a failed or error count" % nm)
    return bad


def ctl_e4(text_queue, text_read, mtime_queue, mtime_read, queue_start, controls_start):
    """e4 tests (r4): the output of the queue kit's test (written by the lead outside the kit folders) and that of this kit's test each carry `N passed` and no failed or error count; the first is not later than the first
    start epoch of the queue, the second not later than the start of the controls stage"""
    bad = _pytest_ok(text_queue, "queue kit") + _pytest_ok(text_read, "reader kit")
    mq, mr, qs, cs = to_epoch(mtime_queue), to_epoch(mtime_read), to_epoch(queue_start), to_epoch(controls_start)
    if mq is None or mr is None or qs is None or cs is None:
        bad.append("a time is missing (queue test %s, reader test %s, queue start %s, controls start %s)" % (mtime_queue, mtime_read, queue_start, controls_start))
    else:
        if not mq <= qs:
            bad.append("the queue kit's test output (%s) is later than the first start epoch of the queue (%s)" % (mq, qs))
        if not mr <= cs:
            bad.append("the reader kit's test output (%s) is later than the start of the controls stage (%s)" % (mr, cs))
    return {"pass": not bad, "failures": bad}


def ctl_e5(per_setting):
    """e5 engine (r5), on each of the three grid reads and the strategic grid: for each of the two settings the engine's own controls of the grid read and of the strategic grid pass (as control g8 of the model reader)"""
    bad, det = [], {}
    if sorted(per_setting) != sorted(SETTINGS):
        bad.append("settings read: %s, expected %s" % (sorted(per_setting), sorted(SETTINGS)))
    for S, v in sorted(per_setting.items()):
        r = MD.ctl_g8(v.get("grid_all_pass"), v.get("strategic_a"), v.get("strategic_b"))
        det[S] = {"grid_all_pass": v.get("grid_all_pass"), "strategic_stage_A_pass": v.get("strategic_a"), "strategic_stage_B_pass": v.get("strategic_b")}
        if not r["PASS"]:
            bad.append("%s: grid_all_pass %s, strategic stage A %s, stage B %s%s" % (S, v.get("grid_all_pass"), v.get("strategic_a"), v.get("strategic_b"),
                                                                                    (" (" + v["strategic_reason"] + ")") if v.get("strategic_reason") else ""))
    return {"pass": not bad, "failures": bad, "per_setting": det}


def ctl_e6(done, n_dumps, expect, done_marker_text=None, leads=None):
    """e6 counts (r6): every new run (the 24 arm runs and the two spread runs) has its done marker and 141 dump files (`expect`); the queue done marker reads `ZZ REPL10K DONE <time> all steps done`; per
    setting the number of windows with a lead of each new model seed equals EXPECT_LEADS (642, 642, 325). done {key: bool}, n_dumps {key: int}, leads {S: {m: int}}"""
    bad = []
    for k in all_run_keys():
        if done.get(k) is not True:
            bad.append("%s: no T1_DONE" % k)
        if n_dumps.get(k) != expect:
            bad.append("%s: %s dump files, %s expected" % (k, n_dumps.get(k), expect))
    if done_marker_text is not None and not DONE_RE.match(last_line(done_marker_text).strip()):
        bad.append("the queue done marker reads %r" % last_line(done_marker_text)[:100])
    for S in SETTINGS:
        for m in SEEDS:
            got = ((leads or {}).get(S) or {}).get(m)
            if got != EXPECT_LEADS[S]:
                bad.append("%s model seed %d: %s windows with a lead, %d expected" % (S, m, got, EXPECT_LEADS[S]))
    return {"pass": not bad, "failures": bad, "values": {"dump_files": n_dumps, "expected": expect, "windows_with_a_lead": {S: {str(m): v for m, v in (d or {}).items()} for S, d in (leads or {}).items()}}}


def ctl_e7(per):
    """e7 rule logs (r7): each new run of GEc and A90 against its own gap file (rule_checks)"""
    bad = []
    if sorted(per) != sorted(rule_keys()):
        bad.append("rollouts read: %d keys, expected %d" % (len(per), len(rule_keys())))
    for k, v in sorted(per.items()):
        bad += ["%s: %s" % (k, x) for x in v.get("failures", [])]
        if v.get("PASS") is not True and not v.get("failures"):
            bad.append("%s: not pass" % k)
    shares = {k: {"share_of_rule_steps_with_a_lead": v.get("share_of_rule_steps_with_a_lead"), "n_rows": v.get("n_rows"), "n_lead_rows": v.get("n_lead_rows"),
                  "share_of_lead_steps_with_nonzero_closing": v.get("share_of_lead_steps_with_nonzero_closing")} for k, v in per.items()}
    return {"pass": not bad and bool(per), "failures": bad, "values": {"rollout_shares": shares}}


def model_ckpt_shas(a):
    """the sha256 of <w>/ckpt/UE_s<m>/A/ckpt_last.pt for the new model seeds (None where the file is absent)"""
    out = {}
    for m in SEEDS:
        p = os.path.join(a.w, "ckpt", "UE_s%d" % m, "A", "ckpt_last.pt") if a.w else ""
        out[m] = sha_file(p) if p and os.path.isfile(p) else None
    return out


def dump_count(pull, nm, mm):
    dd = os.path.join(run_folder(pull, nm, mm), "dump_I10%s_s%d_m10_causal_heads" % (nm, mm))
    return len([f for f in (os.listdir(dd) if os.path.isdir(dd) else []) if f.startswith("ep") and f.endswith(".npz")])


def compute_controls(a, m, wsha):
    """the eight controls from the files on disk and the engine measures `m` ({"settings": {S: {levels_first, grid_all_pass, strategic_a, strategic_b, lead_windows_per_new_seed}}})"""
    c = {}
    mrec = read_json(a.margin_record)
    sb = sha_file(a.gap_file) if a.gap_file and os.path.isfile(a.gap_file) else None
    gap = ctl_gap(mrec, sb, {arm: (sha_file(margin_file(a, arm)) if os.path.isfile(margin_file(a, arm)) else None) for arm in MARGIN_ARMS})
    shas = {"%s_%s_s%d" % (S, arm, mm): MD.run_file_sha(a.pull, run_name(S, arm), mm) for S, arm in new_pairs() for mm in SEEDS}
    present = bool(a.wrapper_check and os.path.isfile(a.wrapper_check) and a.wrapper_hashes and os.path.isfile(a.wrapper_hashes))
    wrap = ctl_wrap(wsha, read_text(a.wrapper_check), read_text(a.wrapper_hashes), present, shas)
    texts = {k: read_text(run_text_path(a.pull, nm, mm)) for k, nm, S, mm in run_list()}
    c["e0"] = ctl_e0(read_json(a.models_record), model_ckpt_shas(a), texts)
    c["e1"] = ctl_e1(gap, wrap)
    lines = {k: (texts[k], read_text(run_text_path(a.pull, nm, mm - 2))) for k, nm, S, mm in run_list()}
    c["e2"] = ctl_e2(lines)
    sets = m.get("settings") or {}
    c["e3"] = ctl_e3({S: (v or {}).get("levels_first") for S, v in sets.items()})
    c["e4"] = ctl_e4(read_text(a.tests_queue), read_text(a.tests_read), a.tests_mtime_queue, a.tests_mtime_read, a.queue_start, a.controls_start)
    c["e5"] = ctl_e5(sets)
    done, n_dumps = {}, {}
    for k, nm, S, mm in run_list():
        done[k] = os.path.isfile(os.path.join(run_folder(a.pull, nm, mm), "T1_DONE"))
        n_dumps[k] = dump_count(a.pull, nm, mm)
    leads = {S: {mm: ((v or {}).get("lead_windows_per_new_seed") or {}).get(str(mm)) for mm in SEEDS} for S, v in sets.items()}
    c["e6"] = ctl_e6(done, n_dumps, int(getattr(a, "expect_dumps", EXPECT_DUMPS)), read_text(a.done_marker) if getattr(a, "done_marker", "") else None, leads)
    c["e7"] = ctl_e7(rule_checks(a))
    return c


def assemble_controls(controls, payload, inputs):
    ok = sorted(controls) == sorted(CONTROLS) and all(isinstance(v, dict) and v.get("pass") is True for v in controls.values())
    vals = {k: v["values"] for k, v in controls.items() if isinstance(v, dict) and "values" in v}
    flat = {k: ({kk: vv for kk, vv in v.items() if kk != "values"} if isinstance(v, dict) else v) for k, v in controls.items()}
    pl = dict(payload)
    pl["control_values"] = vals
    res = {"card": CARD, "tier": TIER, "controls": flat, "all_pass": ok, "inputs": inputs}
    res["payload" if ok else "withheld"] = pl
    return res


# ============================================================================================ names (two separate derivations)
def _sg(iv):
    return -1 if iv[1] < 0.0 else (1 if iv[0] > 0.0 else 0)


def _outside(iv, side):
    """the interval is on the claimed side: below 0 for side -1, above 0 for side +1"""
    return bool(iv[1] < 0.0) if side < 0 else bool(iv[0] > 0.0)


def _opposite(iv, side):
    return bool(iv[0] > 0.0) if side < 0 else bool(iv[1] < 0.0)


def bound_k0(payload):
    """card section 4, printed with no name: the pooled unsafe rate of A90 on the new pair at K0 is at most that of the label form plus CLOSE_TOL"""
    lv = payload["settings"]["K0"]["levels"]
    return bool(lv["A90"]["U"] <= lv["RLc"]["U"] + CLOSE_TOL)


def names_of(payload):
    """card section 4, written from the interval ends: the name of each claim from the interval on the new pair (C claims: the first pair's interval has to be on the claimed side, else `not a claim`),
    and the margin name from M-K0 and M-K30"""
    out, rep = {}, {}
    for X, S, pr, mk, side in CLAIMS:
        est = payload["settings"][S]["est"]
        iv = est["new"][pr][mk]["interval"]
        rep[X] = _outside(iv, side)
        if X in FIRST_PAIR_CLAIMS and not _outside(est["first"][pr][mk]["interval"], side):
            out[X] = NOT_A_CLAIM
        elif _outside(iv, side):
            out[X] = "%s-%s-REPLICATED" % (PRE, X)
        elif _opposite(iv, side):
            out[X] = "%s-%s-OPPOSITE" % (PRE, X)
        else:
            out[X] = "%s-%s-NOT-SEPARATED-ON-THE-NEW-PAIR" % (PRE, X)
    if rep["M-K0"] and rep["M-K30"]:
        out["MARGIN"] = PRE + "-MARGIN-REPLICATED"
    elif rep["M-K0"]:
        out["MARGIN"] = PRE + "-MARGIN-REPLICATED-AT-K0-ONLY"
    elif rep["M-K30"]:
        out["MARGIN"] = PRE + "-MARGIN-REPLICATED-AT-K30-ONLY"
    else:
        out["MARGIN"] = PRE + "-MARGIN-NOT-REPLICATED"
    return out


def derive_all(payload):
    """independent second derivation of every name from the signs of the intervals (written apart from names_of)"""
    out = {}
    got = {}
    for X, S, pr, mk, side in CLAIMS:
        est = payload["settings"][S]["est"]
        s_new = _sg(est["new"][pr][mk]["interval"])
        s_first = _sg(est["first"][pr][mk]["interval"])
        if X in ("C-K0", "C-CONV") and s_first != side:
            out[X] = "not a claim"
        else:
            out[X] = "REPL10K-" + X + "-" + ("REPLICATED" if s_new == side else ("NOT-SEPARATED-ON-THE-NEW-PAIR" if s_new == 0 else "OPPOSITE"))
        got[X] = s_new == side
    tag = {(True, True): "REPLICATED", (True, False): "REPLICATED-AT-K0-ONLY", (False, True): "REPLICATED-AT-K30-ONLY", (False, False): "NOT-REPLICATED"}
    out["MARGIN"] = "REPL10K-MARGIN-" + tag[(got["M-K0"], got["M-K30"])]
    return out


def all_names(payload):
    got = names_of(payload)
    exp = derive_all(payload)
    diff = ["%s: got %s, expected %s" % (k, got.get(k), v) for k, v in sorted(exp.items()) if got.get(k) != v]
    diff += ["%s: name present that the card does not have" % k for k in sorted(got) if k not in exp]
    if diff:
        raise SystemExit("REFUSED: the names are not the ones the intervals give: %s" % diff)
    return got


def flat_names(names):
    return [names[k] for k in sorted(names)]


# ============================================================================================ the pod part (grid read and strategic read per setting)
def register_runs(S):
    spec = SPEC[S]
    for arm, r in spec["runs"].items():
        R.ALL_RUNS.setdefault(r, ("RLc" if arm == "RLc" else "RR", spec["readout"], spec["P"], "deadreckon", spec["grid"], "plan", spec["every"], 0.2))
    R.ALL_RUNS.setdefault(SPREAD, ("R0", "pinned", 0, "deadreckon", "full", "plan", None, 0.2))


class SeedsCtx(object):
    """sets the module global SEEDS of the engine's grid reader (read_longroll10k) and, when it is loaded, that of the strategic reader (strat_roll_read) for one read, then restores both"""

    def __init__(self, seeds):
        self.seeds = tuple(seeds)
        self.old = []

    def __enter__(self):
        mods = [R]
        try:
            import importlib
            mods.append(importlib.import_module("strat_roll_read"))
        except ImportError:
            pass
        for md in mods:
            self.old.append((md, md.SEEDS))
            md.SEEDS = self.seeds
        return self

    def __exit__(self, *exc):
        for md, v in self.old:
            md.SEEDS = v
        return False


class KeyShift(object):
    """the engine's grid reader takes the spread run at its seed label 0 as the reference of the windows, so a read of the model seeds 2 and 3 alone runs with the engine's seed labels (0, 1) and with
    the engine's name of a run (key_of, from which it builds the run, tick and dump folders and its report keys) giving, for the card's own runs at label k, the name of model seed k + shift.
    The engine's files are unchanged; with shift 0 nothing is changed. Found by the lead's rehearsal on banked runs before any model of the second pair existed."""

    def __init__(self, runs, shift):
        self.runs, self.shift = set(runs), int(shift)

    def __enter__(self):
        self.orig = R.key_of
        orig, runs, sh = self.orig, self.runs, self.shift

        def key_of(run, k):
            return orig(run, k + sh if run in runs else k)
        R.key_of = key_of
        return self

    def __exit__(self, *exc):
        R.key_of = self.orig
        return False


class R0Alias(object):
    """the strategic grid compares every run with the unscaled reference run R0 at the same model seed; the card queues the spread run R0Hb20 at the new seeds and no run called R0, so for a model seed
    of 2 or more the tick file of R0 is that of R0Hb20 (the heading bound 0.2 of the card's own runs; the control s5 only compares first ticks). Open decision, written in REPL_READ_DEFS.md."""

    def __enter__(self):
        import importlib
        self.S = importlib.import_module("strat_roll_read")
        self.orig = self.S.tick_path
        orig = self.orig

        def tp(W, run, k):
            return orig(W, SPREAD if (run == "R0" and k >= 2) else run, k)
        self.S.tick_path = tp
        return self

    def __exit__(self, *exc):
        self.S.tick_path = self.orig
        return False


def read_seeds(a, E, S, keys, seeds, log):
    """grid read of the four runs of one setting at the model seeds `seeds` (levels per seed and pooled, pairs with intervals, families), engine calls as in the model reader"""
    spec = SPEC[S]
    runs = spec["runs"]
    pairs_def = {nm: (runs[x], runs[y]) for nm, (x, y) in PAIRS.items()}
    new = tuple(seeds) == SEEDS
    with SeedsCtx(FIRST_SEEDS if new else seeds), KeyShift([SPREAD] + sorted(set(runs.values())), 2 if new else 0):
        G = R.read_grid(a, E, spec["grid"], keys, [SPREAD] + sorted(set(runs.values())), SPREAD, pairs_def, {}, log)
    out = {"seeds": list(seeds), "grid_all_pass": G["controls"].get("ALL_PASS") is True, "counts": G.get("counts") or {}, "levels": {}, "levels_per_seed": {}, "pairs": {}, "families": {}}
    if all(r in (G.get("levels") or {}) for r in runs.values()):
        out["levels"] = {arm: {c: float(np.mean(G["levels"][r][c])) for c in ("C", "U", "F")} for arm, r in runs.items()}
        out["levels_per_seed"] = {arm: {c: [float(v) for v in np.asarray(G["levels"][r][c]).reshape(-1)] for c in ("C", "U", "F")} for arm, r in runs.items()}
    if G.get("pairs"):
        out["pairs"] = {nm: R.ucf(p["headway"]) for nm, p in G["pairs"].items()}
        out["families"] = {nm: {f_: R.reading(R.cells_of(p["family"]), f_) for f_ in R.NAMED} for nm, p in G["pairs"].items()}
    return out


def strat_setting(a, S, keys, ctx_cache, log, out):
    """the strategic grid of one setting at T1-kin: cells of all four model seeds in one pass (the control s3 needs R0 at seed 0), the pair reads on the new pair (seeds 2, 3) only"""
    runs = SPEC[S]["runs"]
    p_of = {"R0": 0}
    p_of.update({r: SPEC[S]["P"] for r in runs.values()})
    try:
        with SeedsCtx(ALL_SEEDS), R0Alias():
            SR, cells_s, eid_s, SS = R.strategic_grid(a, keys, sorted(p_of), p_of, log, ctx_cache)
    except SystemExit as ex:
        out["strategic_reason"] = "SystemExit: %s" % str(ex)[:200]
        return
    except Exception as ex:                                                                   # noqa: BLE001
        out["strategic_reason"] = "%s: %s" % (type(ex).__name__, str(ex)[:200])
        return
    sa, sb = bool(SR.get("stage_A_pass")), bool(SR.get("stage_B_pass"))
    out["strategic_a"], out["strategic_b"] = sa, sb
    out["strategic"]["controls"] = dict({k: v for k, v in SR["controls"].items() if k != "s3"}, s3=SR["controls"]["s3"].get("pass"))
    if sa and sb:
        with SeedsCtx(SEEDS):
            for nm, (x, y) in STRAT_PAIRS.items():
                pr = SS.pair_read(cells_s, runs[x], runs[y], eid_s, ticks=(2,))
                pos = pr["tick2"]["pos"]
                out["strategic"]["pairs"][nm] = {"A": runs[x], "B": runs[y], "pos_30_50_80m_tick_t0_plus_20": [
                    {"arc_m": arc, "mean": b["mean"], "lo": b["lo"], "hi": b["hi"], "verdict": b["verdict"], "n_per_seed": b.get("n_per_seed")} for arc, b in zip(SS.ARCS, pos)],
                    "reading": R.family_of([c["verdict"] for c in pos])}
    else:
        out["strategic_reason"] = "the engine's strategic controls did not pass"


def measure_setting(a, E, S, keys, ctx_cache, log):
    """the three grid reads of one setting (new pair, first pair, four seeds) and the strategic grid"""
    H = E[0]
    register_runs(S)
    reads = {nm: read_seeds(a, E, S, keys, sd, log) for nm, sd in ESTIMATES}
    new = reads["new"]
    out = {"grid_all_pass": all(r["grid_all_pass"] for r in reads.values()), "counts": new["counts"], "levels": new["levels"], "levels_first": reads["first"]["levels"],
           "levels_four": reads["four"]["levels"], "levels_per_seed": reads["four"]["levels_per_seed"], "pairs": new["pairs"], "est": {nm: r["pairs"] for nm, r in reads.items()},
           "families": new["families"], "strategic": {"pairs": {}}, "strategic_a": False, "strategic_b": False}
    if out["counts"]:
        out["instrument_bar_met"] = bool(out["counts"].get("n_lead_windows", 0) >= H.MIN_WINDOWS and out["counts"].get("n_episodes_with_lead", 0) >= H.MIN_EPISODES)
        out["lead_windows_per_new_seed"] = {str(m): out["counts"].get("n_lead_windows") for m in SEEDS}
    strat_setting(a, S, keys, ctx_cache, log, out)
    return out


def grid_path(a, S):
    gf = SPEC[S]["grid_file"]
    return a.grid_pinned if gf == "pinned" else os.path.join(a.grid_dir, gf)


def measure(a, E, log):
    H = E[0]
    J = H.load_join()
    names_ = [str(c) for c in J["clip"]]
    ctx_cache = {}
    res = {}
    for S in SETTINGS:                                                                         # the same code path for the new cells and for the banked cells read as identity
        g = R.jl(grid_path(a, S))
        if g is None:
            res[S] = {"grid_all_pass": False, "levels": {}, "levels_first": {}, "pairs": {}, "strategic_a": False, "strategic_b": False, "strategic_reason": "grid file %s cannot be read" % grid_path(a, S)}
            continue
        keys = R.grid_keys(g, names_)
        res[S] = measure_setting(a, E, S, keys, ctx_cache, log)
    return {"settings": res}


def run_controls(a):
    elog = a.out + ".engine.log"
    if os.path.exists(elog):
        raise SystemExit("REFUSED: %s exists" % elog)
    with io.open(elog, "w", encoding="utf-8", newline="\n") as fh, contextlib.redirect_stdout(fh):
        E = R.engine(a)
        m = measure(a, E, lambda s: print(s, flush=True))
    wsha = sha_file(a.wrapper_file)[:16] if a.wrapper_file and os.path.isfile(a.wrapper_file) else None
    controls = compute_controls(a, m, wsha)
    payload = {"settings": m["settings"], "family_note": FAM_NOTE}
    inputs = {"model_reader": MODEL_PATH and sha_file(MODEL_PATH), "this_reader": sha_file(os.path.abspath(__file__)), "wrapper_file_sha16": wsha,
              "gap_file_sha256": sha_file(a.gap_file) if os.path.isfile(a.gap_file) else None,
              "margin_record_sha256": sha_file(a.margin_record) if os.path.isfile(a.margin_record) else None,
              "models_record_sha256": sha_file(a.models_record) if os.path.isfile(a.models_record) else None}
    return assemble_controls(controls, payload, inputs)


def fmt_pair(p):
    return "; ".join("%s %s" % (label, json.dumps(p[mk], sort_keys=True, default=str)) for mk, label in MEASURES)


def print_sections(payload, names):
    L = ["TIER " + TIER]
    L += flat_names(names)
    L.append("bound, no name: U(A90) <= U(RLc) + %.4f at K0 on the new pair: %s (U(A90) %.4f, U(RLc) %.4f)" % (
        CLOSE_TOL, bound_k0(payload), payload["settings"]["K0"]["levels"]["A90"]["U"], payload["settings"]["K0"]["levels"]["RLc"]["U"]))
    for S in SETTINGS:
        d = payload["settings"][S]
        cn = d.get("counts") or {}
        L.append("setting %s (%s; grid %s): windows %s, windows with a lead %s, episodes with a lead %s, instrument bar of 200 windows and 20 episodes met %s" % (
            S, preroll_text(SPEC[S]["P"]), SPEC[S]["grid"], cn.get("n_windows"), cn.get("n_lead_windows"), cn.get("n_episodes_with_lead"), d.get("instrument_bar_met")))
        for arm in ARMS:
            lv, l1, l4 = d["levels"][arm], d["levels_first"][arm], d["levels_four"][arm]
            L.append("level %s %s pooled new pair C %.4f U %.4f F %.4f; first pair C %.4f U %.4f F %.4f; four seeds C %.4f U %.4f F %.4f; per model seed 0 to 3 %s" % (
                S, arm, lv["C"], lv["U"], lv["F"], l1["C"], l1["U"], l1["F"], l4["C"], l4["U"], l4["F"], json.dumps(d["levels_per_seed"].get(arm), sort_keys=True)))
        for nm in PAIRS:
            for en, _sd in ESTIMATES:
                L.append("%s %s %s: %s" % (S, nm, en, fmt_pair(d["est"][en][nm])))
        for nm in PAIRS:
            st = (d.get("strategic") or {}).get("pairs", {}).get(nm)
            L.append("families %s %s (new pair): %s strategic %s" % (S, nm, json.dumps((d.get("families") or {}).get(nm) or {}, sort_keys=True),
                                                                      st["reading"] if st else "not read (%s)" % d.get("strategic_reason", "no reason recorded")))
        for arm in ARMS:
            dl = {c: d["levels"][arm][c] - d["levels_first"][arm][c] for c in "CUF"}
            L.append("spread between pairs %s %s, pooled level of the new pair minus that of the first pair, no name: C %+.4f U %+.4f F %+.4f" % (S, arm, dl["C"], dl["U"], dl["F"]))
    cv = payload.get("control_values") or {}
    sh = (cv.get("e7") or {}).get("rollout_shares") or {}
    for k in sorted(sh):
        L.append("rollout %s: %s" % (k, json.dumps(sh[k], sort_keys=True)))
    return L


# ============================================================================================ synthetic world for the selftest and the tests
def _write_run(pull, name, m, first, ci, fr, present, gaps, clos=None, sha=None, done=True, ndump=3, meta=True):
    d = os.path.join(pull, "I10%s_s%d" % (name, m))
    os.makedirs(os.path.join(d, "ticks"), exist_ok=True)
    h = len(ci) // 2
    for nm, sl in (("rule_log_I10%s_s%d.npz", slice(0, h)), ("rule_log_mid_I10%s_s%d.npz", slice(h, len(ci)))):
        z = dict(ci=ci[sl], j=fr[sl], present=present[sl], g_src=gaps[sl].copy())
        if clos is not None:
            z["c_src"] = clos[sl]
        if meta:
            z.update(vis_gap_file_sha256=np.array(sha or "none"), vis_closing=np.array(1))
        np.savez(os.path.join(d, "ticks", nm % (name, m)), **z)
    io.open(os.path.join(d, "ticks", "run_I10%s_s%d.txt" % (name, m)), "w", encoding="utf-8", newline="\n").write(first + "\nrc 0 finished x\n")
    if done:
        io.open(os.path.join(d, "T1_DONE"), "w").write("")
    dd = os.path.join(d, "dump_I10%s_s%d_m10_causal_heads" % (name, m))
    os.makedirs(dd, exist_ok=True)
    for i in range(ndump):
        np.savez(os.path.join(dd, "ep%03d.npz" % i), x=np.zeros(1))


def run_line(arm_name, S, m, wrap, form, ref, tail=""):
    """a first line of a run log in the format of the queue (ref True: the banked reference lines of K0 carry no pre-roll, exec, nav or grid field)"""
    sp = SPEC[S]
    ln = "arm I10%s_s%d form %s replan steps 10 rule every %s readout causal_g kappa 0.2" % (arm_name, m, form, sp["every"])
    if not (ref and S == "K0"):
        ln += " preroll %d exec plan nav deadreckon grid %s" % (sp["P"], {"K0": PINNED_GRID_NAME, "K30": "grid_p30.json"}[S])
    ln += " model seed %d reader seed %d ckpt sha256 %s wrapper sha256 %s started 2026-11-22T10:57:07Z%s" % (m, m, ("%02x" % (m + 1)) * 32, wrap, tail)
    return ln


def make_world(base, fault=None):
    """a tiny world (3 clips of 12 frames) in which every control passes (fault None), or exactly the one control named by `fault` fails. -> (a, m, wsha)"""
    base = str(base)
    os.makedirs(base, exist_ok=True)
    pull, gd = os.path.join(base, "pull"), os.path.join(base, "grids")
    for d_ in (pull, gd):
        os.makedirs(d_, exist_ok=True)
    nk = 12
    ci, fr = np.repeat(np.arange(3), nk), np.tile(np.arange(nk), 3)
    n = len(ci)
    clips = np.array(["c0", "c1", "c2"])
    # the evaluation join and the planted join (rows in the layout row = off[ci] + j)
    lv = np.where((fr == 2) | (fr == 3), 0, 1).astype(np.int8)
    lg_eval = (10.0 + fr + 0.5 * ci).astype(np.float32)
    lg_eval[12 + 5] = 40.0                                                             # clip 1 frame 5: a label gap below 60 m, the planted gap below is above 60 m
    lg_jle = lg_eval.copy()
    lg_jle[0] = 21.0
    lg_jle[1] = 22.5
    lg_jle[12 + 5] = 75.0                                                              # camera gap above 60 m on a label row: no lead for the rule
    lg_jle[24 + 7] = np.nan                                                            # a label row with a non-finite gap in the planted join
    ej, jp = os.path.join(base, "join_eval141.npz"), os.path.join(base, "JLE.npz")
    common = dict(clip=clips, off=np.array([0, 12, 24]), n=np.array([12, 12, 12]), lead_valid=lv)
    np.savez(ej, lead_gap=lg_eval, **common)
    np.savez(jp, lead_gap=lg_jle, **common)
    # the base gap file and the LA gap file
    has = np.ones(n, bool)
    has[[2, 14, 30]] = False
    gp = os.path.join(base, "VGAPLE.npz")
    np.savez(gp, clip_index=ci, frame=fr, gap=np.where(has, 15.0 + 0.9 * fr + 0.3 * ci, np.nan), has_out=has, clips=clips, seed=np.int64(-1))
    hasla = np.ones(n, bool)
    hasla[[4, 16, 28]] = False
    lap = os.path.join(base, "VGAPA_LA.npz")
    la_gap = 20.0 + 0.5 * fr + 0.1 * ci
    np.savez(lap, clip_index=ci, frame=fr, gap=np.where(hasla, la_gap, np.nan), has_out=hasla, clips=clips, seed=np.int64(-1))
    la_sha = sha_file(lap)
    # the records
    cl = {"only_lead_gap_differs": True, "unchanged_off_the_named_rows": True, "equals_base_on_the_named_rows": True, "second_routine": True}
    jrec = {"pass_e0": fault != "e0_clause", "clauses": dict(cl, second_routine=fault != "e0_clause"), "counts": {"n_replaced_rows": 30, "n_label_rows": 32, "n_replaced_rows_above_gap_max": 1},
            "join": {"sha256": sha_file(jp) if fault != "e0" else "0" * 64}, "base": {"sha256": sha_file(gp)}, "eval_join_sha256": sha_file(ej)}
    jr = os.path.join(base, "JLE_RECORD.json")
    json.dump(jrec, io.open(jr, "w", encoding="utf-8"))
    gr = os.path.join(base, "GAPERR_GAPFILES_RECORD.json")
    json.dump({"la_file": {"sha256": la_sha if fault != "e7_lafile" else "1" * 64}}, io.open(gr, "w", encoding="utf-8"))
    wrap = WRAPPER_SHA + "0" * 48
    reader_gap = 20.0 + 0.2 * np.arange(n)
    clos = np.where(np.arange(n) % 2 == 0, 0.5, 0.0)
    ones = np.ones(n, bool)
    valid = (lv == 1) & np.isfinite(lg_jle) & (lg_jle >= 0.0) & (lg_jle <= GAP_MAX_M)
    for S in SETTINGS:
        for m in SEEDS:
            # the reference runs: RR (reader gap logged at every lead step; K0 line without optional fields), RLc (text only matters)
            _write_run(pull, run_name(S, "RR"), m, run_line(run_name(S, "RR"), S, m, "f" * 64, "RR", True), ci, fr, ones, reader_gap + 1e-5, clos, meta=False)
            _write_run(pull, run_name(S, "RLc"), m, run_line(run_name(S, "RLc"), S, m, "f" * 64, "RLc", True), ci, fr, valid, np.where(valid, lg_eval, np.nan), None, meta=False)
            # PL: the rule reads its lead from the planted join
            g_pl = np.where(valid, np.nan_to_num(lg_jle) + 1e-5, np.nan)
            pres_pl = valid.copy()
            if S == "K0" and m == 1:
                if fault == "e7":
                    g_pl[1] += 0.5
                if fault == "e7_present":
                    pres_pl[2] = True
                    g_pl[2] = 5.0
                if fault == "e7_missing":
                    pres_pl[4] = False
                if fault == "e7_above":
                    pres_pl[12 + 5] = True
                    g_pl[12 + 5] = 75.0
            first = run_line(run_name(S, "PL"), S, m, wrap if not (fault == "e1_run" and S == "K30" and m == 0) else "e" * 64, "RLc", False, " rule-join /w/JLE.npz rule join sha256 " + "ab" * 32)
            if fault == "e2" and S == "K0" and m == 0:
                first = first.replace("kappa 0.2", "kappa 0.3")
            if fault == "e2_default" and S == "K0" and m == 1:
                first = first.replace("preroll 0", "preroll 30")
            _write_run(pull, run_name(S, "PL"), m, first, ci, fr, pres_pl, g_pl, np.zeros(n), meta=False, done=not (fault == "e6_done" and S == "K30" and m == 0),
                       ndump=3 if not (fault == "e6" and S == "K0" and m == 0) else 2)
            if S == "K0":                                                              # LA at K0: the camera presence, the label gap file VGAPA_LA
                g = np.where(hasla, la_gap, reader_gap) + 1e-5
                if fault == "e7_la" and m == 1:
                    g[3] += 0.5
                c2 = np.zeros(n) if fault == "e7_closing" else clos
                first = run_line(run_name(S, "LA"), S, m, wrap, "RR", False, " vis-gap-file /w/VGAPA_LA.npz gap file sha256 %s vis-closing 1" % la_sha)
                _write_run(pull, run_name(S, "LA"), m, first, ci, fr, ones, g, c2, sha=la_sha if fault != "e7_sha" else "2" * 64)
    chk = os.path.join(base, "CHECK_WRAPPER_V_DONE.txt")
    io.open(chk, "w", encoding="utf-8").write("a\n" + (CHECK_LAST if fault != "e1" else "ZZ CHECK-WRAPPER-V FAIL") + "\n\n")
    hs = os.path.join(base, "CHECK_WRAPPER_V.hashes")
    io.open(hs, "w", encoding="utf-8").write("sha %s\n" % WRAPPER_SHA)
    tq, tr = os.path.join(base, "q_pytest.out"), os.path.join(base, "r_pytest.out")
    io.open(tq, "w", encoding="utf-8").write("....\n12 passed in 3.1s\n")
    io.open(tr, "w", encoding="utf-8").write("....\n== 30 passed, 2 warnings in 9.0s ==\n")

    class A:
        pass
    a = A()
    a.pull, a.grid_dir, a.grid_pinned, a.gap_file, a.gap_record, a.la_file = pull, gd, os.path.join(gd, PINNED_GRID_NAME), gp, gr, lap
    a.jle_file, a.jle_record, a.eval_join, a.expect_dumps = jp, jr, ej, 3
    a.wrapper_check, a.wrapper_hashes, a.tests_queue, a.tests_read = chk, hs, tq, tr
    a.tests_mtime_queue, a.tests_mtime_read, a.queue_start, a.controls_start, a.done_marker = 1000.0, 1010.0, 1100.0, 1200.0, ""
    if fault == "e4":
        a.tests_mtime_read = 1300.0
    lv_ = {S: {arm: dict(zip("CUF", v)) for arm, v in EXPECTED[S].items()} for S in SETTINGS}
    lv_["K0"]["LA"], lv_["K0"]["PL"], lv_["K30"]["PL"] = {"C": 0.0, "U": 0.1, "F": 0.2}, {"C": 0.0, "U": 0.1, "F": 0.2}, {"C": 0.0, "U": 0.1, "F": 0.2}
    if fault == "e3":
        lv_["K30"]["LA"]["U"] += 0.001
    st = {S: {"levels": lv_[S], "grid_all_pass": True, "strategic_a": True, "strategic_b": True} for S in SETTINGS}
    if fault == "e5":
        st["K30"]["strategic_b"] = False
    return a, {"settings": st}, WRAPPER_SHA


def mk_payload(ivs=None):
    """a synthetic payload for the names: ivs = {(setting, pair, measure): interval}; default 'zero' (not separated)"""
    z = [-0.01, 0.01]
    st = {}
    for S in SETTINGS:
        pr = {nm: {m: {"interval": list(z)} for m in "CUF"} for nm in PAIRS}
        for (s2, nm, m), iv in (ivs or {}).items():
            if s2 == S:
                pr[nm][m]["interval"] = list(iv)
        st[S] = {"levels": {arm: {"C": 0.0, "U": 0.1, "F": 0.5} for arm in ARMS}, "pairs": pr}
    return {"settings": st}


def selftest():
    ok = True
    bind(os.environ.get("PRESATTR_MODEL_READER", ""))
    with tempfile.TemporaryDirectory() as td:
        for fault in (None,) + CONTROLS:
            a, m, wsha = make_world(os.path.join(td, "w_%s" % fault), fault)
            c = compute_controls(a, m, wsha)
            flags = {k: v["pass"] for k, v in c.items()}
            want = {k: (k != fault) for k in CONTROLS}
            if flags != want:
                print("SELFTEST fault %s: flags %s" % (fault, flags))
                ok = False
    ok &= MD.WRAPPER_SHA == WRAPPER_SHA and MD.CHECK_LAST == CHECK_LAST
    hi = [0.01, 0.05]
    nm = all_names(mk_payload({("K0", "GEc-VS-PL", "U"): hi}))
    ok &= nm["K0_OVERALL"] == PRE + "-K0-PRESENCE-CARRIES-UNSAFE" and nm["K30_OVERALL"] == PRE + "-K30-UNSAFE-NOT-ATTRIBUTED"
    print("ZZ READ-REPL10K SELFTEST %s" % ("OK" if ok else "FAIL"))
    return 0 if ok else 1


def main(argv=None):
    argv = sys.argv[1:] if argv is None else argv
    ap = argparse.ArgumentParser(allow_abbrev=False)
    ap.add_argument("--stage", choices=("controls", "names"))
    ap.add_argument("--selftest", action="store_true")
    for nme in ("pull", "code", "grid-dir", "grid-pinned", "w", "tree", "wrapper-file", "wrapper-check", "wrapper-hashes", "controls", "gap-file", "gap-record", "margin-dir", "margin-record", "models-record",
                "eval-join", "tests-queue", "tests-read", "tests-mtime-queue", "tests-mtime-read", "queue-start", "controls-start", "done-marker", "model-reader"):
        ap.add_argument("--" + nme, default="")
    ap.add_argument("--out", default="")
    ap.add_argument("--log", default="")
    ap.add_argument("--n-boot", type=int, default=2000)
    ap.add_argument("--expect-dumps", type=int, default=EXPECT_DUMPS)
    a = ap.parse_args(argv)
    if a.selftest:
        print("REFUSED: the selftest is tied to the world of the source readers and is not part of this kit")
        return 2
    if not a.stage or not a.out:
        print("REFUSED: --stage and --out are required")
        return 2
    bind(a.model_reader)
    a.n_boot_control = 300
    if os.path.exists(a.out):
        print("REFUSED: %s exists" % a.out)
        return 2
    if a.stage == "controls":
        a.gap_file = a.gap_file or WS + "/cropscale/gapfiles/VGAPLE.npz"
        a.gap_record = a.gap_record or WS + "/gaperr/gapfiles/GAPERR_GAPFILES_RECORD.json"
        a.margin_dir = a.margin_dir or WS + "/gapmargin/gapfiles"
        a.margin_record = a.margin_record or a.margin_dir + "/GAPMARGIN_GAPFILES_RECORD.json"
        a.models_record = a.models_record or WS + "/repl/models/REPL_MODELS_RECORD.json"
        a.grid_pinned = a.grid_pinned or WS + "/hierrep/pins/" + PINNED_GRID_NAME
        a.tests_queue = a.tests_queue or WS + "/repl/lead_tests/lead_pytest_queue.out"
        a.tests_read = a.tests_read or WS + "/repl/lead_tests/lead_pytest_read.out"
        res = run_controls(a)
        io.open(a.out, "w", encoding="utf-8", newline="\n").write(json.dumps(res, indent=1, default=lambda o: float(o) if hasattr(o, "item") else str(o)))
        for k in CONTROLS:
            print("%s %s" % (k, "PASS" if (res["controls"].get(k) or {}).get("pass") else "FAIL"))
        print("ZZ READ-REPL10K controls all_pass %s" % res["all_pass"])
        return 0
    cj = read_json(a.controls) or {}
    if cj.get("card") != CARD or cj.get("all_pass") is not True or "payload" not in cj or sorted(cj.get("controls", {})) != sorted(CONTROLS) \
            or any((v or {}).get("pass") is not True for v in cj.get("controls", {}).values()):
        print("REFUSED: the controls file is not all-pass with e0 to e7 present: no name is written")
        print("ZZ READ-REPL10K names refused")
        return 3
    logp = a.log or (os.path.splitext(a.out)[0] + "_names.log")
    if os.path.exists(logp):
        print("REFUSED: %s exists" % logp)
        return 2
    names = all_names(cj["payload"])
    res = {"card": CARD, "tier": TIER, "controls_file": os.path.abspath(a.controls), "controls_sha256": sha_file(a.controls), "names": names, "values": cj["payload"]}
    io.open(a.out, "w", encoding="utf-8", newline="\n").write(json.dumps(res, indent=1))
    lines = print_sections(cj["payload"], names) + ["ZZ READ-REPL10K names done"]
    io.open(logp, "w", encoding="utf-8", newline="\n").write("\n".join(lines) + "\n")
    for ln in lines:
        print(ln)
    return 0


try:
    bind(os.environ.get("PRESATTR_MODEL_READER", ""))
except ImportError as _ex:                      # bound again in main() from --model-reader; a missing one is reported there
    print("NOTE: %s" % _ex, file=sys.stderr)

if __name__ == "__main__":
    sys.exit(main())
